import{_ as a,o as p,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const g=JSON.parse('{"title":"《佛经 · 药师经》","description":"","frontmatter":{"title":"《佛经 · 药师经》","date":"2026-11-24T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 药师经》","tags":["佛经","唐"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"玄奘 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·药师经/index.md","filePath":"blogs/佛经·药师经/index.md"}'),l={name:"blogs/佛经·药师经/index.md"};function c(u,s,d,v,t,o){return p(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="《佛经-·-药师经》" tabindex="-1">《佛经 · 药师经》 <a class="header-anchor" href="#《佛经-·-药师经》" aria-label="Permalink to &quot;《佛经 · 药师经》&quot;">​</a></h1><p class="poem-meta">唐 · 玄奘 译</p><p>全文 51 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="药师琉璃光如来本愿功德经" tabindex="-1">药师琉璃光如来本愿功德经 <a class="header-anchor" href="#药师琉璃光如来本愿功德经" aria-label="Permalink to &quot;药师琉璃光如来本愿功德经&quot;">​</a></h3><div class="sutra"><div class="su-pair"><p class="su-org">如是我闻：一时薄伽梵，游化诸国，至广严城，住乐音树下。与大苾刍众八千人俱，菩萨摩诃萨三万六千，及国王、大臣，婆罗门、居士，天龙八部，人非人等，无量大众，恭敬围绕，而为说法。</p><p class="su-tra">这部经是我亲耳听佛说的。那时薄伽梵（世尊）在各国游化，到了广严城，住在乐音树下。与八千位大苾刍（比丘）在一起，又有菩萨摩诃萨三万六千，以及国王、大臣、婆罗门、居士，天龙八部、人非人等无量大众，恭敬围绕，佛为他们说法。</p></div><div class="su-pair"><p class="su-org">尔时、曼殊室利法王子，承佛威神，从座而起，偏袒一肩，右膝著地，向薄伽梵，曲躬合掌。白言：“世尊！惟愿演说如是相类诸佛名号，及本大愿殊胜功德，令诸闻者业障销除，为欲利乐像法转时诸有情故”。</p><p class="su-tra">这时，曼殊室利（文殊师利）法王子承佛的威神，从座而起，偏露一肩，右膝着地，向着世尊曲躬合掌，说道：“世尊！唯愿您演说这一类诸佛的名号，以及他们本来的大愿和殊胜功德，让听到的人业障消除——也是为了利益安乐像法转时的种种有情。”</p></div><div class="su-pair"><p class="su-org">尔时、世尊赞曼殊室利童子言：“善哉！善哉！曼殊室利！汝以大悲，劝请我说诸佛名号，本愿功德，为拔业障所缠有情，利益安乐像法转时诸有情故。汝今谛听！极善思惟！当为汝说”。</p><p class="su-tra">这时世尊赞叹曼殊室利童子说：“好啊，好啊！曼殊室利！你以大悲，劝请我说诸佛名号与本愿功德，为了拔除被业障缠缚的有情，为了利益安乐像法转时的种种有情。你现在仔细听，好好思维，我要为你说。”</p></div><div class="su-pair"><p class="su-org">曼殊室利言：“唯然，愿说！我等乐闻！”</p><p class="su-tra">曼殊室利说：“是的，世尊！愿您宣说，我们都乐意听。”</p></div><div class="su-pair"><p class="su-org">佛告曼殊室利：“东方去此，过十殑伽沙等佛土，有世界名净琉璃，佛号药师琉璃光如来、应、正等觉，明行圆满、善逝、世间解、无上士、调御丈夫、天人师、佛、薄伽梵。”</p><p class="su-tra">佛告诉曼殊室利：“从这东方去，越过十条恒河沙数那样的佛土，有个世界名叫净琉璃，那里的佛号药师琉璃光如来、应、正等觉、明行圆满、善逝、世间解、无上士、调御丈夫、天人师、佛、薄伽梵。”</p></div><div class="su-pair"><p class="su-org">“曼殊室利！彼世尊药师琉璃光如来本行菩萨道时，发十二大愿，令诸有情，所求皆得”。</p><p class="su-tra">“曼殊室利！那位世尊药师琉璃光如来当初行菩萨道的时候，发了十二个大愿，让诸有情所求都能如愿。”</p></div><div class="su-pair"><p class="su-org">“第一大愿：愿我来世，得阿耨多罗三藐三菩提时，自身光明炽然照耀无量无数无边世界，以三十二大丈夫相，八十随形庄严其身；令一切有情如我无异”。</p><p class="su-tra">“第一大愿：愿我来世证得无上正等正觉时，自身的光明炽然照耀无量无数无边的世界，以三十二大丈夫相、八十随形好庄严其身，让一切有情都和我一样。”</p></div><div class="su-pair"><p class="su-org">“第二大愿：愿我来世得菩提时，身如琉璃，内外明彻，净无瑕秽；光明广大，功德巍巍，身善安住，燄网庄严过于日月；幽冥众生，悉蒙开晓，随意所趣，作诸事业”。</p><p class="su-tra">“第二大愿：愿我来世得菩提时，身如琉璃，内外明彻，清净没有瑕秽；光明广大，功德巍巍，身安稳住，焰网庄严超过日月；幽冥中的众生都蒙开导晓喻，随意所向，做成种种事业。”</p></div><div class="su-pair"><p class="su-org">“第三大愿：愿我来世得菩提时，以无量无边智慧方便，令诸有情皆得无尽所受用物，莫令众生，有所乏少”。</p><p class="su-tra">“第三大愿：愿我来世得菩提时，以无量无边的智慧方便，让诸有情都得到受用不尽的东西，不叫众生有所缺乏。”</p></div><div class="su-pair"><p class="su-org">“第四大愿：愿我来世得菩提时，若诸有情行邪道者，悉令安住菩提道中；若行声闻独觉乘者，皆以大乘而安立之”。</p><p class="su-tra">“第四大愿：愿我来世得菩提时，如果诸有情有行邪道的，都让他们安住菩提道中；如果行声闻、独觉乘的，都用大乘来安立他们。”</p></div><div class="su-pair"><p class="su-org">“第五大愿：愿我来世得菩提时，若有无量无边有情，于我法中修行梵行，一切皆令得不缺戒、具三聚戒；设有毁犯，闻我名已还得清净，不堕恶趣！”</p><p class="su-tra">“第五大愿：愿我来世得菩提时，若有无量无边的有情在我这法中修梵行，都叫他们得戒不缺、具足三聚净戒；万一有毁犯的，听到我的名号便还得清净，不再堕恶趣。”</p></div><div class="su-pair"><p class="su-org">“第六大愿：愿我来世得菩提时，若诸有情，其身下劣，诸根不具，丑陋、顽愚、盲、聋、瘖、哑、挛躄、背偻、白癞、颠狂、种种病苦；闻我名已，一切皆得端正黠慧，诸根完具，无诸疾苦”。</p><p class="su-tra">“第六大愿：愿我来世得菩提时，若诸有情下身下劣、诸根不具，丑陋、顽愚、盲、聋、哑、瘸跛、驼背、白癞、颠狂，种种病苦的；听到我的名号，都得以端正聪慧、诸根完具，没有疾病之苦。”</p></div><div class="su-pair"><p class="su-org">“第七大愿：愿我来世得菩提时，若诸有情众病逼切，无救无归，无医无药，无亲无家，贫穷多苦；我之名号一经其耳，众病悉除，身心安乐，家属资具悉皆丰足，乃至证得无上菩提”。</p><p class="su-tra">“第七大愿：愿我来世得菩提时，若诸有情被众病所逼，无救无归、无医无药、无亲无家，贫穷多苦；我的名号一经他的耳朵，众病都除，身心安乐，家属资具都丰足，一直到证得无上菩提。”</p></div><div class="su-pair"><p class="su-org">“第八大愿：愿我来世得菩提时，若有女人为女百恶之所逼恼，极生厌离，愿舍女身；闻我名已，一切皆得转女成男，具丈夫相，乃至证得无上菩提”。</p><p class="su-tra">“第八大愿：愿我来世得菩提时，若有女人被女身的百种恶所逼恼，极生厌离、愿舍女身；听到我的名号，都得以转女成男、具丈夫相，一直到证得无上菩提。”</p></div><div class="su-pair"><p class="su-org">“第九大愿：愿我来世得菩提时，令诸有情出魔罥网，解脱一切外道缠缚；若堕种种恶见稠林，皆当引摄置于正见，渐令修习诸菩萨行，速证无上正等菩提！”</p><p class="su-tra">“第九大愿：愿我来世得菩提时，让诸有情出离魔的罗网，解脱一切外道的缠缚；若堕在种种恶见的密林里，都要引摄他们安立于正见，渐次修习诸菩萨行，速证无上正等菩提。”</p></div><div class="su-pair"><p class="su-org">“第十大愿：愿我来世得菩提时，若诸有情王法所录，绳缚鞭挞，系闭牢狱，或当刑戮，及余无量灾难凌辱，悲愁煎逼，身心受苦；若闻我名，以我福德威神力故，皆得解脱一切忧苦！”</p><p class="su-tra">“第十大愿：愿我来世得菩提时，若诸有情被王法所拘，绳缚鞭打、关在牢狱，或当受刑戮，以及其余无量的灾难凌辱、悲愁煎迫、身心受苦；若闻我的名号，靠我福德威神的缘故，都得以解脱一切忧苦。”</p></div><div class="su-pair"><p class="su-org">“第十一大愿：愿我来世得菩提时，若诸有情饥渴所恼，为求食故造诸恶业；得闻我名，专念受持，我当先以上妙饮食饱足其身，后以法味毕竟安乐而建立之”。</p><p class="su-tra">“第十一大愿：愿我来世得菩提时，若诸有情被饥渴所恼，为求食而造诸恶业；得闻我的名号，专念受持，我当先以上妙的饮食让他吃饱，再以法味使他究竟安乐而安立之。”</p></div><div class="su-pair"><p class="su-org">“第十二大愿：愿我来世得菩提时，若诸有情贫无衣服，蚊虻寒热，昼夜逼恼；若闻我名，专念受持，如其所好即得种种上妙衣服，亦得一切宝庄严具，华鬘、涂香，鼓乐众伎，随心所玩，皆令满足”。</p><p class="su-tra">“第十二大愿：愿我来世得菩提时，若诸有情贫穷无衣，蚊虻寒热昼夜逼恼；若闻我的名号，专念受持，就照他所好得到种种上妙衣服，也得到一切宝庄严具、华鬘、涂香、鼓乐众伎，随心所玩，都令满足。”</p></div><div class="su-pair"><p class="su-org">“曼殊室利！是为彼世尊药师琉璃光如来、应、正等觉行菩萨道时，所发十二微妙上愿”。</p><p class="su-tra">“曼殊室利！这就是那位世尊药师琉璃光如来、应、正等觉行菩萨道时所发的十二个微妙上愿。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！彼世尊药师琉璃光如来行菩萨道时，所发大愿，及彼佛土功德庄严，我若一劫、若一劫余，说不能尽。然彼佛土，一向清净，无有女人，亦无恶趣，及苦音声；琉璃为地，金绳界道，城阙宫阁，轩窗罗网，皆七宝成；亦如西方极乐世界，功德庄严，等无差别。于其国中，有二菩萨摩诃萨：一名日光遍照，二名月光遍照。是彼无量无数菩萨众之上首，次补佛处，悉能持彼世尊药师琉璃光如来正法宝藏。是故曼殊室利！诸有信心善男子、善女人等，应当愿生彼佛世界”。</p><p class="su-tra">“再说，曼殊室利！那位世尊药师琉璃光如来行菩萨道时所发的大愿，以及那佛国土的功德庄严，我就算说一劫、说一劫多也说不尽。但那佛土一向清净，没有女人，也没有恶趣和痛苦的声音；琉璃作地，金绳划道，城阙宫阁、轩窗罗网都是七宝所成，也和西方极乐世界一样，功德庄严没有差别。那国中有两位菩萨摩诃萨：一名日光遍照，二名月光遍照，是无量无数菩萨众的上首，依次补佛之位，都能荷持那位世尊药师琉璃光如来的正法宝藏。所以，曼殊室利！一切有信心、善男子、善女人，都应当愿生那佛的世界。”</p></div><div class="su-pair"><p class="su-org">尔时、世尊，复告曼殊室利童子言：“曼殊室利！有诸众生，不识善恶，惟怀贪吝，不知布施及施果报，愚痴无智，阙于信根，多聚财宝，勤加守护。见乞者来，其心不喜，设不获已而行施时，如割身肉，深生痛惜。复有无量悭贪有情，积集资财，于其自身尚不受用，何况能与父母、妻子、奴婢作使，及来乞者？彼诸有情，从此命终生饿鬼界，或傍生趣。由昔人间曾得暂闻药师琉璃光如来名故，今在恶趣，暂得忆念彼如来名，即于念时从彼处没，还生人中；得宿命念，畏恶趣苦，不乐欲乐，好行惠施，赞叹施者，一切所有悉无贪惜，渐次尚能以头目手足血肉身分施来求者，况余财物？”</p><p class="su-tra">这时世尊又告诉曼殊室利童子：“曼殊室利！有些众生不识善恶，只怀着贪心吝啬，不懂得布施和布施的果报，愚痴无智，缺了信根，积聚财宝，勤苦守护。看见乞人来，心里不高兴；万不得已行一次布施，就像割自己的肉，深深地痛惜。还有无量悭贪的有情，积了钱财，连自己都不肯受用，何况给父母、妻子、奴婢僮仆和来乞讨的人？这些众生从此命终，生到饿鬼界，或堕畜生道。由于过去在人间曾经暂时听过药师琉璃光如来的名号，如今在恶趣中偶尔忆念起那如来名号，就在那一念时从那里命终，还生人中；得宿命念，怕恶趣的苦，不贪欲乐，喜好布施，赞叹施主，所有东西都不贪惜，渐次连头目手足血肉身分都能施给来求的人，何况其余财物？”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若诸有情，虽于如来受诸学处，而破尸罗；有虽不破尸罗而破轨则；有于尸罗、轨则，虽则不坏，然毁正见；有虽不毁正见而弃多闻，于佛所说契经深义不能解了；有虽多闻而增上慢，由增上慢覆蔽心故，自是非他，嫌谤正法，为魔伴党。如是愚人，自行邪见，复令无量俱胝有情，堕大险坑。此诸有情，应于地狱、傍生鬼趣流转无穷。若得闻此药师琉璃光如来名号，便舍恶行，修诸善法，不堕恶趣；设有不能舍诸恶行、修行善法，堕恶趣者，以彼如来本愿威力令其现前，暂闻名号，从彼命终还生人趣，得正见精进，善调意乐，便能舍家趣于非家，如来法中，受持学处无有毁犯，正见多闻，解甚深义，离增上慢，不谤正法，不为魔伴，渐次修行诸菩萨行，速得圆满”。</p><p class="su-tra">“再说，曼殊室利！若诸有情，虽然在如来那里受了种种学处，却破了尸罗（戒）；有虽不破戒却破了轨则；有于戒与轨则虽不坏，却毁了正见；有虽不毁正见却舍弃多闻，于佛所说的契经深义不能解了；有多闻却起增上慢——因为增上慢覆蔽其心，自以为是、说别人不是，嫌恨诽谤正法，做魔的伴党。这样的愚人，自己行邪见，又让无量俱胝有情堕入大险坑。这些众生本应在地狱、畜生、鬼趣中流转无穷。若能闻这药师琉璃光如来名号，便舍恶行、修诸善法，不堕恶趣；万一舍不掉恶行、修不起善法而堕了恶趣，靠那如来的本愿威力，让他现前暂时闻得名号，也从那里命终还生人趣，得正见精进，善于调伏意乐，便能舍家、趣于非家，在如来法中受持学处、无所毁犯，正见多闻，解甚深义，远离增上慢，不谤正法、不做魔伴，渐次修行诸菩萨行，速得圆满。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若诸有情悭贪、嫉妒，自赞毁他，当堕三恶趣中，无量千岁受诸剧苦！受剧苦已，从彼命终，来生人间，作牛马驼驴，恒被鞭挞，饥渴逼恼，又常负重随路而行。或得为人，生居下贱，作人奴婢，受他驱役，恒不自在。若昔人中曾闻世尊药师琉璃光如来名号，由此善因，今复忆念，至心归依。以佛神力，众苦解脱，诸根聪利，智慧多闻，恒求胜法，常遇善友，永断魔罥，破无明壳，竭烦恼河，解脱一切生老病死忧愁苦恼”。</p><p class="su-tra">“再说，曼殊室利！若诸有情悭贪、嫉妒，自我称赞、毁谤他人，当堕三恶趣中，无量千岁受种种剧苦。受剧苦已，从那里命终，来生人间，做牛、马、驼、驴，恒常被鞭打，饥渴逼恼，又要常负重物随路而行；或得为人，生在卑下之处，做人奴婢，受驱使，常不自在。若从前在人间曾闻世尊药师琉璃光如来名号，靠这善因，如今又忆念起来，至心归依——以佛的神力，众苦解脱，诸根聪利，智慧多闻，恒求胜法，常遇善友，永断魔网，破无明壳，枯竭烦恼之河，解脱一切生老病死忧愁苦恼。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若诸有情好喜乖离，更相斗讼，恼乱自他，以身语意，造作增长种种恶业，展转常为不饶益事，互相谋害。告召山林树冢等神；杀诸众生，取其血肉祭祀药叉、罗刹婆等；书怨人名，作其形像，以恶咒术而咒诅之；厌魅蛊道，咒起尸鬼，令断彼命，及坏其身。是诸有情，若得闻此药师琉璃光如来名号，彼诸恶事悉不能害，一切展转皆起慈心，利益安乐，无损恼意及嫌恨心，各各欢悦，于自所受生于喜足，不相侵凌互为饶益”。</p><p class="su-tra">“再说，曼殊室利！若诸有情喜好乖张背离，互相争斗诉讼、恼乱自他，以身语意造作增长种种恶业，展转常做不饶益的事、互相谋害：去祷告召唤山林树冢等神；杀种种众生，取其血肉祭祀药叉、罗刹婆等；写下怨人的名字，做他的形像，用恶咒术去诅咒他；厌魅、蛊道，咒起尸鬼，要断彼性命、坏彼身体。这些有情若能闻这药师琉璃光如来名号，那些恶事都不能加害，彼此展转都生起慈心，互相利益安乐，没有损害恼怒之意和嫌恨之心，各各欢悦，对自己所得生喜足心，不相侵凌、互为饶益。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若有四众：苾刍、苾刍尼、邬波索迦、邬波斯迦，及余净信善男子、善女人等，有能受持八分斋戒，或经一年、或复三月受持学处，以此善根，愿生西方极乐世界无量寿佛所听闻正法而未定者，若闻世尊药师琉璃光如来名号，临命终时，有八大菩萨，其名曰：文殊师利菩萨，观世音菩萨，得大势菩萨，无尽意菩萨，宝檀华菩萨，药王菩萨，药上菩萨，弥勒菩萨。是八大菩萨乘空而来，示其道路，即于彼界种种杂色众宝华中，自然化生”。</p><p class="su-tra">“再说，曼殊室利！若有四众——苾刍、苾刍尼、邬波索迦、邬波斯迦，以及其余净信的善男子、善女人，能受持八分斋戒，或经一年、或经三个月，如法受持学处，靠这善根愿生西方极乐世界无量寿佛处听闻正法，而心尚未决定的——若闻世尊药师琉璃光如来名号，临命终时，有八大菩萨前来：一名文殊师利菩萨，二名观世音菩萨，三名得大势菩萨，四名无尽意菩萨，五名宝檀华菩萨，六名药王菩萨，七名药上菩萨，八名弥勒菩萨。这八大菩萨乘空而来，示其道路，就在那界中种种杂色的众宝花里自然化生。”</p></div><div class="su-pair"><p class="su-org">“或有因此，生于天上，虽生天上，而本善根，亦未穷尽，不复更生诸余恶趣。天上寿尽，还生人间，或为轮王，统摄四洲，威德自在，安立无量百千有情于十善道；或生刹帝利、婆罗门、居士大家，多饶财宝，仓库盈溢，形相端正，眷属具足，聪明智慧，勇健威猛，如大力士。若是女人，得闻世尊药师琉璃光如来名号，至心受持，于后不复更受女身”。</p><p class="su-tra">“也有人因此生于天上；虽生天上，本来的善根也没有用尽，不再更生其余恶趣。天上寿尽，还生人间：或作转轮王，统摄四洲，威德自在，把无量百千有情安立在十善道上；或生在刹帝利、婆罗门、居士大户人家，多饶财宝，仓库盈溢，形相端正，眷属具足，聪明智慧，勇健威猛如大力士。若是女人，得闻世尊药师琉璃光如来名号，至心受持，以后就不再受女身。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！彼药师琉璃光如来得菩提时，由本愿力，观诸有情，遇众病苦瘦挛、干消、黄热等病；或被厌魅、蛊毒所中；或复短命，或时横死；欲令是等病苦消除所求愿满”。</p><p class="su-tra">“再说，曼殊室利！那位药师琉璃光如来得菩提时，由本愿力，观察诸有情遇种种病苦——消瘦挛缩、干消、黄热等病；或被厌魅、蛊毒所中；或者短命，或者横死——为使这些病苦消除、所求如愿。”</p></div><div class="su-pair"><p class="su-org">“时彼世尊，入三摩地，名曰除灭一切众生苦恼。既入定已，于肉髻中出大光明，光中演说，大陀罗尼曰：‘那谟薄伽筏帝，裨杀社窭噜，薜琉璃钵剌婆喝啰阇也，怛陀揭多耶，阿罗诃帝，三藐三勃陀耶。怛姪阤：唵，鞞杀逝，鞞杀逝，鞞杀社，三没揭帝娑诃’”。尔时、光中说此咒已，大地震动，放大光明，一切众生病苦皆除，受安隐乐。”</p><p class="su-tra">“那时那位世尊入于三摩地，名叫‘除灭一切众生苦恼’。入定之后，从肉髻中出大光明，光中演说着大陀罗尼：‘归敬世尊——药师琉璃光如来、应供、正等觉。即说咒曰：唵，除病啊除病，除一切病，令得正觉，圆满成就。’（这段咒是梵语的音译，意思是这样。）这时光中说完此咒，大地震动，放大光明，一切众生的病苦都除，得到安稳之乐。”</p></div><div class="su-pair"><p class="su-org">“曼殊室利！若见男子女人有病苦者，应当一心，为彼病人，常清净澡漱，或食或药或无虫水、咒一百八遍，与彼服食，所有病苦悉皆消灭。若有所求，至心念诵，皆得如是无病延年；命终之后，生彼世界，得不退转，乃至菩提。是故曼殊室利！若有男子、女人，于彼药师琉璃光如来，至心殷重，恭敬供养者，常持此咒，勿令废忘”。</p><p class="su-tra">“曼殊室利！若看见男子、女人有病苦的，应当一心为那病人：常净刷牙漱口，或在食中、药中、或无虫的水中，咒一百八遍，给他服食，所有病苦都能消灭。若有所求，至心念诵，都得这样的无病延年；命终之后生那世界，得不退转，乃至菩提。所以曼殊室利！若男子、女人对于那位药师琉璃光如来至心殷重、恭敬供养的，应当常持此咒，不要废忘。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若有净信男子女人，得闻药师琉璃光如来应正等觉所有名号，闻已诵持。晨嚼齿木，澡漱清净，以诸香花，烧香、涂香，作众伎乐，供养形象。于此经典，若自书，若教人书，一心受持，听闻其义。于彼法师，应修供养：一切所有资身之具，悉皆施与，勿令乏少。如是便蒙诸佛护念，所求愿满，乃至菩提”。</p><p class="su-tra">“再说，曼殊室利！若有净信的善男子、善女人，得闻药师琉璃光如来应正等觉的名号，闻了诵持；清晨嚼齿木（刷牙），澡漱清净，用种种香花、烧香、涂香，作众伎乐供养佛像；对这经典，自己抄写、或教人抄写，一心受持，听闻其义；对那法师应当修供养，一切资身之具都施与他，不令乏少——这样便蒙诸佛护念，所求如愿，乃至菩提。”</p></div><div class="su-pair"><p class="su-org">尔时、曼殊室利童子白佛言：“世尊！我当誓于像法转时，以种种方便，令诸净信善男子、善女人等，得闻世尊药师琉璃光如来名号，乃至睡中亦以佛名觉悟其耳。世尊！若于此经受持读诵。或复为他演说开示；若自书、若教人书；恭敬尊重，以种种华香、涂香、末香、烧香、花鬘、璎珞、幡盖、伎乐，而为供养；以五色彩，作囊盛之；扫洒净处，敷设高座，而用安处。尔时、四大天王与其眷属，及余无量百千天众，皆诣其所，供养守护。世尊！若此经宝流行之处，有能受持，以彼世尊药师琉璃光如来本愿功德，及闻名号，当知是处无复横死；亦复不为诸恶鬼神夺其精气，设已夺者，还得如故，身心安乐”。</p><p class="su-tra">这时曼殊室利童子对佛说：“世尊！我当在像法转时，用种种方便，发誓让诸净信的善男子、善女人得闻世尊药师琉璃光如来名号，乃至在睡梦中也用佛名唤醒他的耳朵。世尊！若有人对这经受持读诵，或为他人演说开示；自己抄写、教人抄写；恭敬尊重，用种种华香、涂香、末香、烧香、花鬘、璎珞、幡盖、伎乐来供养；用五色彩的帛做成袋子盛装；打扫净处，敷设高座安放它——那时四大天王与其眷属，以及其余无量百千天众都到他那里，供养守护。世尊！若这经宝流通之处，有人能受持，靠那位世尊药师琉璃光如来的本愿功德，以及闻名号的缘故，当知那地方不再有天折横死，也不会被诸恶鬼神夺其精气；即使已被夺去的，也还得如故，身心安乐。”</p></div><div class="su-pair"><p class="su-org">佛告曼殊室利：“如是！如是！如汝所说。曼殊室利！若有净信善男子、善女人等，欲供养彼世尊药师琉璃光如来者，应先造立彼佛形像，敷清净座而安处之。散种种花，烧种种香，以种种幢幡庄严其处。七日七夜，受八分斋戒，食清净食，澡浴香洁，著清净衣，应生无垢浊心，无怒害心，于一切有情起利益安乐，慈悲喜舍平等之心，鼓乐歌赞，右遶佛像。复应念彼如来本愿功德，读诵此经，思惟其义，演说开示。随所乐求，一切皆遂：求长寿，得长寿，求富饶，得富饶，求官位得官位，求男女得男女”。</p><p class="su-tra">佛告诉曼殊室利：“正是，正是，如同你说的。曼殊室利！若有净信的善男子、善女人要供养那位世尊药师琉璃光如来的，应当先造立那佛的形像，铺清净座安放它；散种种花，烧种种香，用种种幢幡庄严其处；七日七夜受八分斋戒，吃清净食，沐浴香洁，穿清净衣，应当生无垢浊心、无怒害心，对一切有情起利益安乐、慈悲喜舍平等之心，鼓乐歌赞，右绕佛像。还应当念那如来的本愿功德，读诵此经，思惟其义，演说开示。随他想要什么，一切都能如愿：求长寿得长寿，求富饶得富饶，求官位得官位，求男女得男女。”</p></div><div class="su-pair"><p class="su-org">“若复有人，忽得恶梦，见诸恶相；或怪鸟来集；或于住处百怪出现。此人若以众妙资具，恭敬供养彼世尊药师琉璃光如来者，恶梦、恶相诸不吉祥，皆悉隐没，不能为患。或有水火刀毒、悬险恶象、师子虎狼、熊罴毒蛇、恶蝎蜈蚣、蚰蜒蚊虻等布；若能至心忆念彼佛，恭敬供养，一切怖畏皆得解脱。若他国侵扰，盗贼反乱，忆念恭敬彼如来者，亦皆解脱”。</p><p class="su-tra">“若有人忽然做了恶梦，见了种种恶相；或有怪鸟来集；或住处出现百种怪异。这人若能用种种妙好的资具恭敬供养那位世尊药师琉璃光如来，恶梦、恶相种种不吉祥都会隐没，不能为患。或者有水火、刀毒、悬险、恶象，狮子、虎狼、熊罴、毒蛇、恶蝎、蜈蚣、蚰蜒、蚊虻之类遍布；若能至心忆念那佛、恭敬供养，一切怖畏都得解脱。若他国侵扰、盗贼反乱，忆念恭敬那如来的，也都解脱。”</p></div><div class="su-pair"><p class="su-org">“复次、曼殊室利！若有净信善男子、善女人等，乃至尽形不事余天，唯当一心，归佛法僧，受持禁戒：若五戒、十戒，菩萨四百戒、苾刍二百五十戒，苾刍尼五百戒。于所受中或有毁犯，怖堕恶趣，若能专念彼佛名号，恭敬供养者，必定不受三恶趣生。或有女人，临当产时，受于极苦；若能至心称名礼赞，恭敬供养彼如来者，众苦皆除。所生之子，身分具足，形色端正，见者欢喜，利根聪明，安隐少病，无有非人，夺其精气”。</p><p class="su-tra">“再说，曼殊室利！若有净信的善男子、善女人，乃至尽形命不事奉其余诸天，只当一心归依佛、法、僧，受持禁戒——若五戒、十戒、菩萨四百戒、苾刍二百五十戒、苾刍尼五百戒——在所受的戒中若有毁犯、害怕堕恶趣的，若能专念那佛名号、恭敬供养，必定不再受三恶趣之生。又有女人临产时受极大苦；若能至心称名礼赞、恭敬供养那如来，众苦都除。所生的孩子身分具足，形色端正，见者欢喜，利根聪明，安稳少病，没有非人来夺他的精气。”</p></div><div class="su-pair"><p class="su-org">尔时、世尊告阿难言：“如我称扬彼世尊药师琉璃光如来所有功德，此是诸佛甚深行处，难可解了，汝为信不？”</p><p class="su-tra">这时世尊告诉阿难：“像我这样称扬那位世尊药师琉璃光如来所有的功德，这是诸佛甚深的行处，很难信解——你能信吗？”</p></div><div class="su-pair"><p class="su-org">阿难白言：“大德世尊！我于如来所说契经不生疑惑，所以者何？一切如来身语意业无不清净。世尊！此日月轮可令堕落，妙高山王可使倾动，诸佛所言无有异也”。</p><p class="su-tra">阿难说：“大德世尊！我对如来所说的契经不生疑惑。为什么？一切如来的身、语、意业无不清净。世尊！日轮月轮可以让它坠落，妙高山王可以让它倾动，诸佛说的话不会有差错。”</p></div><div class="su-pair"><p class="su-org">“世尊！有诸众生，信根不具，闻说诸佛甚深行处，作是思惟：云何但念药师琉璃光如来一佛名号，便获尔所功德胜利？由此不信，返生诽谤。彼于长夜失大利乐，堕诸恶趣，流转无穷！”</p><p class="su-tra">“世尊！有些众生信根不具足，听说诸佛甚深行处，就这样想：怎么可能只念一尊药师琉璃光如来的名号，便得这样的功德胜利？因为不信，反倒生起诽谤。他在长夜里失去大利之乐，堕诸恶趣，流转无穷！”</p></div><div class="su-pair"><p class="su-org">佛告阿难：“是诸有情若闻世尊药师琉璃光如来名号，至心受持，不生疑惑，堕恶趣者无有是处”。</p><p class="su-tra">佛告诉阿难：“这些众生若闻世尊药师琉璃光如来名号，至心受持、不生疑惑，那么堕恶趣是没有的事。”</p></div><div class="su-pair"><p class="su-org">“阿难！此是诸佛甚深所行，难可信解；汝今能受，当知皆是如来威力。阿难！一切声闻、独觉，及未登地诸菩萨等，皆悉不能如实信解，唯除一生所系菩萨。阿难！人身难得；于三宝中，信敬尊重，亦难可得闻世尊药师琉璃光如来名号，复难于是”。</p><p class="su-tra">“阿难！这是诸佛甚深所行的境界，难可信解；你今天能受，当知都是如来的威力。阿难！一切声闻、独觉，以及还没登地的诸菩萨，都不能如实信解，只除了一生所系的菩萨。阿难！人身难得；在三宝中能信敬尊重，也很难得；能闻世尊药师琉璃光如来名号，比这又更难。”</p></div><div class="su-pair"><p class="su-org">“阿难！彼药师琉璃光如来，无量菩萨行，无量善巧方便，无量广大愿；我若一劫，若一劫余而广说者，劫可速尽，彼佛行愿，善巧方便无有尽也！”</p><p class="su-tra">“阿难！那位药师琉璃光如来有无量的菩萨行、无量的善巧方便、无量的广大誓愿；我要是一劫或一劫多地细说，劫可以很快说完，那佛的行愿和善巧方便却说不尽！”</p></div><div class="su-pair"><p class="su-org">尔时、众中，有一菩萨摩诃萨，名曰救脱，即从座起，偏袒一肩，右膝著地，曲躬合掌而白佛言：“大德世尊！像法转时，有诸众生为种种患之所困厄，长病赢瘦，不能饮食，喉唇干燥，见诸方暗，死相现前，父母亲属、朋友知识啼泣围绕；然彼自身卧在本处，见琰魔使，引其神识至于琰魔法王之前。然诸有情，有俱生神，随其所作若罪若福，皆具书之，尽持授与琰魔法王。尔时、彼王推问其人，计算所作，随其罪福而处断之。时彼病人，亲属、知识，若能为彼归依世尊药师琉璃光如来，请诸众僧，转读此经，然七层之灯，悬五色续命神幡，或有是处彼识得还，如在梦中明了自见。或经七日，或二十一日，或三十五日，或四十九日，彼识还时，如从梦觉，皆自忆知善不善业所得果报；由自证见业果报故，乃至命难，亦不造作诸恶之业。是故净信善男子善女人等，皆应受持药师琉璃光如来名号，随力所能，恭敬供养”。</p><p class="su-tra">这时会众中有一位菩萨摩诃萨，名叫救脱，从座而起，偏露一肩，右膝着地，曲躬合掌对佛说：“大德世尊！像法转时，有种种众生被诸患困厄：长久生病、瘦弱不堪，不能饮食，喉唇干燥，眼前一片黑暗，死相现前，父母亲属、朋友知识啼哭围绕。他自己卧在本处，却看见琰魔的差役，引其神识到琰魔法王面前。诸有情各有一个与身俱来的神，随着他所做的或罪或福一一记下来，全部拿去交给琰魔法王。那时那王审问此人，计算他所做的，随其罪福加以裁断。那时那病人的亲属、知识，若能为他归依世尊药师琉璃光如来，请诸众僧转读此经，点燃七层之灯，悬起五色的续命神幡——就有他神识还阳的可能，如同在梦中自己看得分明。或经七日、二十一日、三十五日、四十九日，他神识回来时，如从梦醒，都能自己记得善恶业所得的果报；因为亲自证见了业果，所以乃至性命难关，也不再造诸恶业。所以净信的善男子、善女人都应当受持药师琉璃光如来名号，随力所能，恭敬供养。”</p></div><div class="su-pair"><p class="su-org">尔时、阿难问救脱菩萨曰：“善男子！应云何恭敬供养彼世尊药师琉璃光如来？续命幡灯复云何造”？救脱菩萨言：“大德！若有病人，欲脱病苦，当为其人，七日七夜受持八分斋戒。应以饮食及余资具，随力所办，供养苾刍僧。昼夜六时，礼拜供养彼世尊药师琉璃光如来。读诵此经四十九遍，然四十九灯；造彼如来形像七躯，一一像前各置七灯，一一灯量大如车轮，乃至四十九日光明不绝。造五色彩幡，长四十九搩手，应放杂类众生至四十九，可得过度危厄之难，不为诸横恶鬼所持”。</p><p class="su-tra">这时阿难问救脱菩萨：“善男子！应当怎样恭敬供养那位世尊药师琉璃光如来？续命的幡和灯又该怎么做？”救脱菩萨说：“大德！若有病人要脱离病苦，应当为他七日七夜受持八分斋戒；应以饮食及其他资具，随力办备，供养苾刍僧；昼夜六时礼拜供养那位世尊药师琉璃光如来；读诵此经四十九遍，点燃四十九盏灯；造那如来形像七尊，一一像前各放七盏灯，一一灯大如车轮，乃至四十九日光明不断；做五色彩幡，长四十九搩手；应放杂类众生到四十九——这样可以度过危厄之难，不被诸横恶鬼所持。”</p></div><div class="su-pair"><p class="su-org">“复次、阿难！若刹帝利、灌顶王等，灾难起时，所谓：人众疾疫难，他国侵逼难，自界叛逆难，星宿变怪难，日月薄蚀难，非时风雨难，过时不雨难。彼刹帝利灌顶王等，尔时应于一切有情起慈悲心，赦诸系闭。依前所说供养之法，供养彼世尊药师琉璃光如来。由此善根及彼如来本愿力故，令其国界即得安隐，风雨顺时，谷稼成熟，一切有情无病欢乐。于其国中，无有暴恶药叉等神恼有情者，一切恶相皆即隐没；而刹帝利灌顶王等寿命色力，无病自在，皆得增益”。</p><p class="su-tra">“再说，阿难！若刹帝利、灌顶王等遇到灾难起时，所谓：人众疾疫难、他国侵逼难、自界叛逆难、星宿变怪难、日月薄蚀难、非时风雨难、过时不雨难——那刹帝利、灌顶王等，那时应当对一切有情起慈悲心，赦免被拘禁的人；照前面所说的供养之法，供养那位世尊药师琉璃光如来。靠这善根和那如来的本愿力，其国界立刻安隐，风雨应时，谷稼成熟，一切有情无病欢乐；国中没有暴恶的药叉等神恼乱有情，一切恶相随即隐没；而刹帝利、灌顶王等的寿命、色力、无病自在，都得增益。”</p></div><div class="su-pair"><p class="su-org">“阿难！若帝后妃主，储君王子，大臣辅相，中宫彩女，百官黎庶，为病所苦，及余厄难；亦应造立五色神幡，然灯续明，放诸生命，散杂色花，烧众名香；病得除愈，众难解脱”。</p><p class="su-tra">“阿难！若帝后、妃主、储君、王子、大臣、辅相、中宫彩女、百官黎庶，被病所苦以及其余厄难，也应当造立五色神幡，燃灯续明，放诸生命，散杂色花，烧众名香——病就得痊愈，众难都得解脱。”</p></div><div class="su-pair"><p class="su-org">尔时，阿难问救脱菩萨言：“善男子！云何已尽之命而可增益”？救脱菩萨言：“大德！汝岂不闻如来说有九横死耶？是故劝造续命幡灯，修诸福德，以修福故，尽其寿命不经苦患”。阿难问言：“九横云何”？救脱菩萨言：“若诸有情，得病虽轻，然无医药及看病者，设复遇医，授以非药，实不应死而便横死。又信世间邪魔外道妖孽之师妄说祸福，便生恐动，心不自正，卜问觅祸，杀种种众生，解奏神明，呼诸魍魉，请乞福祐，欲冀延年，终不能得。愚痴迷惑，信邪倒见，遂令横死入于地狱，无有出期，是名初横。二者、横被王法之所诛戮。三者、畋猎嬉戏，耽淫嗜酒，放逸无度，横为非人夺其精气。四者、横为火焚。五者、横为水溺。六者、横为种种恶兽所噉。七者、横堕山崖。八者、横为毒药、厌祷、咒诅、起尸鬼等之所中害。九者、饥渴所困，不得饮食而便横死。是为如来略说横死，有此九种，其余复有无量诸横，难可具说！</p><p class="su-tra">这时阿难问救脱菩萨：“善男子！已经该尽的命，怎么还能增益呢？”救脱菩萨说：“大德！你难道没听如来说有九种横死吗？所以劝人造续命幡灯、修诸福德——以修福的缘故，尽其寿命不经过苦患。”阿难问：“九种横死是哪九种？”救脱菩萨说：“一者，有情得病虽轻，却没有医药和看护的人；即使遇到医生，给了不对症的药——本来不该死，就这样横死。又有信世间邪魔外道、妖孽之师妄说祸福，便心生恐动，心不自正，卜问觅祸，杀种种众生，解奏神明，呼诸魍魉，请乞福祐，想要延年，终究不能得；愚痴迷惑、信邪倒见，遂令横死又堕入地狱，无有出期——这是第一横。二者，横被王法所诛戮。三者，田猎嬉戏、耽淫嗜酒、放逸无度，横被非人夺其精气。四者，横为火焚。五者，横为水溺。六者，横为种种恶兽所啖。七者，横堕山崖。八者，横为毒药、厌祷、咒诅、起尸鬼等所中害。九者，饥渴所困，得不到饮食而便横死。这是如来略说的横死，有此九种；其余还有无量诸横，难以具说！”</p></div><div class="su-pair"><p class="su-org">“复次、阿难！彼琰魔王主领世间名籍之记，若诸有情，不孝五逆，破辱三宝，坏君臣法，毁于性戒，琰魔法王随罪轻重，考而罚之。是故我今劝诸有情，然灯造幡，放生修福，令度苦厄，不遭众难”。</p><p class="su-tra">“再说，阿难！那位琰魔王主领世间的名籍记录。若诸有情不孝、犯五逆，破辱三宝，破坏君臣之法，毁犯性戒——琰魔法王便随罪的轻重考核惩罚他。所以我今天劝诸有情：燃灯造幡、放生修福，让人度脱苦厄、不遭众难。”</p></div><div class="su-pair"><p class="su-org">尔时、众中有十二药叉大将，俱在会坐，所谓：宫毘罗大将，伐折罗大将，迷企罗大将，安底罗大将，頞你罗大将，珊底罗大将，因达罗大将，波夷罗大将，摩虎罗大将，真达罗大将，招杜罗大将，毘羯魔大将：此十二药叉大将，一一各有七千药叉，以为眷属。</p><p class="su-tra">这时会众中有十二药叉大将都在座，所谓：宫毗罗大将、伐折罗大将、迷企罗大将、安底罗大将、頞你罗大将、珊底罗大将、因达罗大将、波夷罗大将、摩虎罗大将、真达罗大将、招杜罗大将、毗羯魔大将。这十二药叉大将，每一大将各有七千药叉做眷属。</p></div><div class="su-pair"><p class="su-org">同时举声白佛言：“世尊！我等今者蒙佛威力，得闻世尊药师琉璃光如来名号，不复更有恶趣之怖。我等相率，皆同一心，乃至尽形归佛法僧，誓当荷负一切有情，为作义利，饶益安乐。随于何等村城国邑，空闲林中，若有流布此经，或复受持药师琉璃光如来名号恭敬供养者，我等眷属卫护是人，皆使解脱一切苦难，诸有愿求悉令满足。或有疾厄求度脱者，亦应读诵此经，以五色缕，结我名字，得如愿已，然后解结”。</p><p class="su-tra">他们同时举声对佛说：“世尊！我们如今蒙佛威力，得闻世尊药师琉璃光如来名号，不再有害怕堕恶趣之忧。我们相率一同发心，乃至尽形命归依佛、法、僧，誓愿荷负一切有情，为他们作义利、饶益安乐。无论在什么村、城、国、邑，或空闲林中，若有流布此经、或受持药师琉璃光如来名号恭敬供养的人，我们眷属都卫护这人，使他解脱一切苦难，有愿求的都令满足。若有疾病困厄要求度脱的，也应当读诵此经，用五色缕结上我们的名字，等如愿之后，再把结解开。”</p></div><div class="su-pair"><p class="su-org">尔时、世尊赞诸药叉大将言：“善哉！善哉！大药叉将！汝等念报世尊药师琉璃光如来恩德者，常应如是利益安乐一切有情”。</p><p class="su-tra">这时世尊赞叹诸药叉大将说：“好啊，好啊！大药叉将！你们若念报世尊药师琉璃光如来的恩德，就应当常这样利益安乐一切有情。”</p></div><div class="su-pair"><p class="su-org">尔时、阿难白佛言：“世尊！当何名此法门？我等云何奉持？”佛告阿难：此法门名说药师琉璃光如来本愿功德；亦名说十二神将饶益有情结愿神咒；亦名拔除一切业障；应如是持”！</p><p class="su-tra">这时阿难对佛说：“世尊！这个法门该叫什么名字？我们应当怎样奉持？”佛告诉阿难：“此法门名《说药师琉璃光如来本愿功德》，也名《说十二神将饶益有情结愿神咒》，也名《拔除一切业障》——应当这样奉持！”</p></div><div class="su-pair"><p class="su-org">时薄伽梵说是语已，诸菩萨摩诃萨，及大声闻，国王、大臣、婆罗门、居士、天龙、药叉、健达缚、阿素洛、揭路荼、紧捺洛、莫呼洛伽、人、非人等一切大众，闻佛所说，皆大欢喜，信受奉行。</p><p class="su-tra">薄伽梵说完这话，诸菩萨摩诃萨和大声闻，国王、大臣、婆罗门、居士，天龙、药叉、健达缚、阿素洛、揭路荼、紧捺洛、莫呼洛伽、人非人等一切大众，闻佛所说，皆大欢喜，信受奉行。</p></div></div></div>',4)])])}const n=a(l,[["render",c]]);export{g as __pageData,n as default};
